from pathlib import Path
import json, html
R=Path(__file__).resolve().parents[1]
T=json.loads((R/'brand-settings.json').read_text()); URL=T['links']['dashboard']
logo='<img class="logo" src="../logos/nextjobber-wordmark-primary.svg" alt="NextJobber" width="330" height="54">'
css='''*{box-sizing:border-box}body{margin:0;color:#241C24;background:#FBF7F9;font-family:Arial,sans-serif;line-height:1.6}a{color:inherit}button,input,textarea,select{font:inherit}button,a,input,textarea,select{touch-action:manipulation}:focus-visible{outline:3px solid #a95177;outline-offset:4px}header,main,footer{max-width:1200px;margin:auto;padding:32px}.logo{max-width:100%;height:auto}header{display:flex;align-items:center;justify-content:space-between;gap:24px}header a{text-decoration:none}nav{display:flex;gap:24px;align-items:center}.button,button{background:#4C1734;color:white;border:0;border-radius:8px;padding:13px 22px;text-decoration:none;display:inline-block;cursor:pointer}.secondary{background:white;color:#4C1734;border:1px solid #d8cbd1}h1{font-size:clamp(42px,6vw,78px);line-height:1.08;letter-spacing:-2px;font-weight:500}h2{font-size:32px;line-height:1.2;font-weight:500}h3{font-size:21px}.muted,p{color:#766B70}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase}.hero{padding:56px 0 80px}.hero p{max-width:620px;font-size:21px}.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}.split img{max-width:100%;border-radius:18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:28px;background:white;border:1px solid #e5dbe0;border-radius:16px}.card a{display:block;margin-top:9px}.card p{font-size:14px}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}section{padding:28px 0}label{display:block;font-size:14px;margin:18px 0}input,textarea,select{display:block;width:100%;padding:12px;border:1px solid #cbbdc4;background:white;border-radius:6px;color:#241C24}small{color:#766B70}footer{font-size:13px;border-top:1px solid #e5dbe0;margin-top:40px}.preview{background:white;padding:16px;border:1px solid #e5dbe0}.preview svg{width:100%;height:auto;display:block}.color{display:inline-block;width:90px;height:90px;border-radius:14px;margin-right:14px}.links{max-width:620px;margin:60px auto;text-align:center}.links .button{display:block;margin:16px}.wide{width:100%}@media(max-width:800px){header{display:block}nav{margin-top:20px}.split,.grid{grid-template-columns:1fr}.hero{padding-top:10px}.logo{width:270px}main,header,footer{padding:24px}h1{letter-spacing:-1px}}@media print{nav,button,.noprint{display:none}body{background:white}.card{break-inside:avoid}}'''
def page(title,body):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+css+'</style></head><body>'+body+'</body></html>'

landing=f'''<header>{logo}<nav><a href="#how">How it works</a><a href="#questions">Questions</a><a class="button" href="{URL}">Open NextJobber</a></nav></header><main><section class="hero split"><div><div class="eyebrow">Career exploration and job search</div><h1>Your next career step,<br>with a plan.</h1><p>Explore what fits your experience. Find the evidence to support your next application.</p><a class="button" href="{URL}">Explore careers</a></div><img src="../mockups/laptop-concept.png" alt="Illustrative NextJobber laptop brand mockup"></section><section id="how"><h2>A place to make progress</h2><div class="grid"><article><h3>Understand what you bring</h3><p>Reflect on your interests, work values, and transferable skills.</p></article><article><h3>Compare real opportunities</h3><p>Review job requirements alongside examples from your experience.</p></article><article><h3>Prepare your next step</h3><p>Work on applications, learning plans, and follow-up actions.</p></article></div></section><section id="questions"><h2>Useful to know</h2><details><summary>What do the assessments measure?</summary><p>They are original self-reflection questionnaires for career exploration. They are not validated aptitude tests.</p></details><details><summary>What jobs does the built-in feed include?</summary><p>Recent remote listings. Available job-search tools in chat can support broader searches.</p></details><details><summary>Can I open the current workspace?</summary><p>The current private release requires the owner account. Review access before sharing this template publicly.</p></details></section></main><footer>{logo}<p>NextJobber. Your next career step, with a plan.</p></footer>'''
(R/'websites/landing-page.html').write_text(page('NextJobber | Career exploration',landing))
linkbody=f'<main class="links"><img width="130" height="130" src="../icons/nextjobber-profile-plum.png" alt="NextJobber NJ symbol"><h1>What comes next?</h1><p>Choose a place to start.</p><a class="button" href="{URL}">Open your career workspace</a><a class="button secondary" href="{T["links"]["plugin"]}">View the ChatGPT plugin</a><a class="button secondary" href="landing-page.html">Explore NextJobber</a><small>Current release: private access for the owner account.</small></main>'
(R/'websites/link-page.html').write_text(page('NextJobber | Links',linkbody))

categories=[('Brandkit Settings','brand-settings.json','Color, type, spacing, and usage settings.'),('Logo Files','logos/nextjobber-wordmark-primary.svg','Outlined SVG masters, transparent PNGs, and print PDF.'),('Brand Guides','guidelines/NextJobber_Brand_Guide.pdf','Guidelines in PDF and editable Markdown.'),('Websites','websites/landing-page.html','Responsive landing page and link-page templates.'),('Profile Icons','icons/nextjobber-profile-plum.png','Three colorways, favicons, and app icon sizes.'),('Mockups','mockups/stationery.png','Generated stationery and laptop concept mockups.'),('Business Cards','print/business-card-front.pdf','Front and back with bleed and editable contact fields.'),('Facebook Covers','social/facebook-cover-plum.png','Two 1640 × 624 cover designs.'),('Instagram Posts','social/instagram-post-introduction.png','Three editable post designs.'),('Instagram Stories','social/instagram-story-explore.png','Three editable 1080 × 1920 story designs.'),('Presentations','presentations/NextJobber_Presentation_Template.pptx','Editable six-slide PowerPoint starter.'),('Animations','animations/nextjobber-reveal.mp4','Logo reveal in MP4, GIF, and animated SVG.'),('QR Code','qr/nextjobber-dashboard-qr.png','Vector and raster QR, with destination notes.'),('Invoices','print/NextJobber_Invoice_Template.docx','Editable Word and printable PDF templates.'),('Design Tool','studio/index.html','Edit a branded poster and export SVG or PNG.'),('Enterprise Chat','support/support-widget.html','Support widget prototype and response library.'),('Download Fonts','fonts/README.md','Font files and redistribution license.')]
(R/'asset-categories.json').write_text(json.dumps([dict(category=a,path=b,description=c)for a,b,c in categories],indent=2))
cards=''.join(f'<article class="card"><h3>{a}</h3><p>{c}</p><a href="{b}">Open {a.lower()}</a></article>' for a,b,c in categories)
index='<header><img class="logo" src="logos/nextjobber-wordmark-primary.svg" alt="NextJobber"><nav><a href="studio/index.html">Design studio</a><a href="guidelines/NextJobber_Brand_Guide.pdf">Brand guide</a></nav></header><main><section class="hero"><div class="eyebrow">Brand kit 1.0</div><h1>One identity.<br>Ready for your next step.</h1><p>Original logo artwork and editable assets for NextJobber.</p><a class="button" href="studio/index.html">Open the brand studio</a></section><div class="grid">'+cards+'</div></main><footer>Replace contact placeholders before use. The current QR destination is private. The support widget is a local prototype.</footer>'
(R/'START-HERE.html').write_text(page('NextJobber brand kit',index))

word=(R/'logos/nextjobber-wordmark-primary.svg').read_text()
symbol=(R/'logos/nextjobber-symbol.svg').read_text()
studio=f'''<header>{logo}<nav><a href="../START-HERE.html">All assets</a></nav></header><main><h1>Make it yours.</h1><p>Edit a poster, save brand settings, and export your design.</p><div class="split" style="align-items:start"><section><h2>Brandkit settings</h2><label>Primary color<input type="color" id="color" value="#4C1734"></label><label>Secondary color<input type="color" id="secondary" value="#766B70"></label><button id="settings">Download settings JSON</button><h2>Design tool</h2><label>Headline, one line per row<textarea id="headline" rows="3">Your next\ncareer step,\nwith a plan.</textarea></label><label>Supporting line<input id="subline" value="Explore what fits. Build the evidence."></label><label>Canvas<select id="format"><option value="1080,1080">Square post · 1080 × 1080</option><option value="1080,1350">Portrait post · 1080 × 1350</option><option value="1080,1920">Story · 1080 × 1920</option></select></label><label>Background<select id="theme"><option value="light">Paper</option><option value="dark">Plum</option></select></label><div class="row"><button id="svg">Download SVG</button><button id="png" class="secondary">Download PNG</button></div><p id="status" role="status"></p></section><section><h2>Preview</h2><div class="preview" id="preview"></div><p><small>Your edits stay in this page until you export them. No upload is needed.</small></p></section></div></main>'''
js=r'''<script>const master=__MASTER__;const initial=__SETTINGS__;const el=id=>document.getElementById(id);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));function make(){const[w,h]=el('format').value.split(',').map(Number);const dark=el('theme').value==='dark';const p=el('color').value,g=el('secondary').value;const bg=dark?p:'#FBF7F9',fg=dark?'#FFFFFF':p;let y=h>1500?380:280;let lines=el('headline').value.split('\n').slice(0,5);let parts=lines.map(s=>{const line=`<text x="72" y="${y}" font-family="Arial,sans-serif" font-size="82" font-weight="700" fill="${fg}">${esc(s.slice(0,23))}</text>`;y+=110;return line}).join('');let logo=master.replace(/<svg[^>]*>/,'').replace('</svg>','').replaceAll('#4C1734',fg).replaceAll('#766B70',dark?'#E3B4C6':g);return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="${w}" height="${h}" fill="${bg}"/>${parts}<text x="76" y="${y+35}" font-family="Arial,sans-serif" font-size="25" fill="${dark?'#E3B4C6':g}">${esc(el('subline').value.slice(0,68))}</text><g transform="translate(25 ${h-145}) scale(.62)">${logo}</g></svg>`}function update(){el('preview').innerHTML=make()}function save(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);el('status').textContent='Your download is ready.'}for(const id of['color','secondary','headline','subline','format','theme'])el(id).addEventListener('input',update);el('svg').onclick=()=>save(new Blob([make()],{type:'image/svg+xml'}),'nextjobber-design.svg');el('settings').onclick=()=>{const d=structuredClone(initial);d.colors.plum=el('color').value;d.colors.warmGray=el('secondary').value;save(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),'nextjobber-brand-settings.json')};el('png').onclick=async()=>{const image=new Image();const uri=URL.createObjectURL(new Blob([make()],{type:'image/svg+xml'}));image.onload=()=>{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);c.toBlob(b=>save(b,'nextjobber-design.png'));URL.revokeObjectURL(uri)};image.onerror=()=>{el('status').textContent='PNG export could not load. Download the SVG instead.';URL.revokeObjectURL(uri)};image.src=uri};update();</script>'''.replace('__MASTER__',json.dumps(word)).replace('__SETTINGS__',json.dumps(T))
(R/'studio/index.html').write_text(page('NextJobber brand studio',studio+js))

support=f'''<header>{logo}<nav><a href="../START-HERE.html">Brand kit</a></nav></header><main style="max-width:760px"><h1>Brand support</h1><p>This local support-widget prototype answers common brand-kit questions. Messages stay in this page and do not reach a support team.</p><section class="card"><div id="thread" role="log" aria-live="polite"><p>How can I help with the NextJobber kit?</p></div><label>Choose a topic<select id="topic"><option value="logo">Which logo file should I use?</option><option value="edit">How do I edit a template?</option><option value="qr">Where does the QR code go?</option><option value="help">How do I request design support?</option></select></label><button id="ask">Show answer</button></section><p><a href="response-library.md">Open the editable support response library</a></p></main><script>const answers={{logo:'Use SVG for editable vector artwork, PNG for images, and the white wordmark on a plum background. Use the NJ icon at small sizes.',edit:'Open the design studio for a poster export. Edit SVG text in a vector editor, DOCX in Word, and PPTX in PowerPoint. Font files are included.',qr:'The QR opens the existing private dashboard. Review its destination and access before sharing or printing it.',help:'This prototype has no live team connected. Add your chosen support address or helpdesk integration before offering enterprise chat.'}};document.getElementById('ask').onclick=()=>{{const p=document.createElement('p');p.textContent=answers[document.getElementById('topic').value];document.getElementById('thread').append(p)}};</script>'''
(R/'support/support-widget.html').write_text(page('NextJobber brand support prototype',support))
(R/'support/response-library.md').write_text('# Brand support response library\n\n## Logo files\nUse SVG for scalable artwork and PNG for image uploads. Choose the white version on plum. Use the NJ icon for small profile and app uses.\n\n## Template edits\nOpen the design studio for an SVG or PNG poster. Open DOCX files in Word and PPTX files in PowerPoint. Install the included font files to match the template typography.\n\n## Contact details\nReplace every bracketed field with approved business details before distribution.\n\n## QR destination\nThe current QR points to a private dashboard. Confirm the intended audience can open the destination before printing.\n\n## Enterprise support setup\nChoose a support address, staffing arrangement, and helpdesk provider. Define hours, routing, and response expectations. This kit provides prototype UI and response copy only.\n')
print('Web templates, studio, support prototype and asset index created.')
